"""E76 verdict (rules registered in docs/EVIDENCE.md): python experiments/robot/analyse_e76.py results/e76 -> results/e76/REPORT_E76.md"""
import json, sys, numpy as np
root = sys.argv[1]; L = lambda a, s: json.load(open(f"{root}/ladder/{a}_s{s}.json")); T = lambda s: json.load(open(f"{root}/out/train_s{s}.json")); S = range(5)
J, U = [L("J", s) for s in S], [L("U", s) for s in S]
fmt = lambda x, n=3: f"{x:.{n}f}"
md = ["# E76 report (generated by experiments/robot/analyse_e76.py)", "", "## Per seed (J = trained JEPA, U = same encoder untrained)", "",
      "| Seed | Arm | camera acc from V1 | camera acc from Q1 | rung-1 d | rung-1 gap | viewpoint ratio V1/Q1 | rung-2 d / gap | rung-3 d / gap | layout R2 (full / core Q3) | progress R2 (V3 / core Q3) |", "|---|---|---|---|---|---|---|---|---|---|---|"]
for s in S:
    for a, r in (("J", J[s]), ("U", U[s])):
        md.append(f"| {s} | {a} | {fmt(r['camera_acc']['from_V1'])} | {fmt(r['camera_acc']['from_Q1'])} | {r['rung1']['d']} | {fmt(r['rung1']['gap_ratio'], 2)} | {fmt(r['viewpoint_ratio_V1_over_Q1'], 2)} | {r['rung2']['d']} / {fmt(r['rung2']['gap_ratio'], 2)} | {r['rung3']['d']} / {fmt(r['rung3']['gap_ratio'], 2)} | {fmt(r['layout_R2']['full'], 2)} / {fmt(r['layout_R2']['core_Q3'], 2)} | {fmt(r['progress_R2']['V3'], 2)} / {fmt(r['progress_R2']['core_Q3'], 2)} |")
nA = sum(r["camera_acc"]["from_V1"] >= 0.9 and r["camera_acc"]["from_Q1"] <= 0.6 for r in J); nB = sum(r["rung1"]["gap_ratio"] >= 2 for r in J)
rj, ru = np.mean([r["viewpoint_ratio_V1_over_Q1"] for r in J]), np.mean([r["viewpoint_ratio_V1_over_Q1"] for r in U]); dC = rj - ru
a_ok, b_ok, c_ok = nA >= 3, nB >= 3, dC >= 1.0
md += ["", "## Registered lines", "",
       f"- (a) camera isolated (acc from V1 >= 0.9 and from Q1 <= 0.6) on at least 3 of 5 J seeds: observed {nA} of 5 (acc from V1: {', '.join(fmt(r['camera_acc']['from_V1'], 2) for r in J)}; from Q1: {', '.join(fmt(r['camera_acc']['from_Q1'], 2) for r in J)}): **{'met' if a_ok else 'NOT met, short by %d seed(s)' % (3 - nA)}**",
       f"- (b) rung-1 gap ratio >= 2 on at least 3 of 5 J seeds: observed {nB} of 5 (gaps {', '.join(fmt(r['rung1']['gap_ratio'], 2) for r in J)}): **{'met' if b_ok else 'NOT met, short by %d seed(s); largest gap %.2f, required 2, short by %.2f' % (3 - nB, max(r['rung1']['gap_ratio'] for r in J), 2 - max(r['rung1']['gap_ratio'] for r in J))}**",
       f"- (c) viewpoint ratio J minus U on the seed mean >= 1.0: J {fmt(rj, 2)}, U {fmt(ru, 2)}, difference {fmt(dC, 2)}: **{'met' if c_ok else 'NOT met, short by %.2f' % (1.0 - dC)}**",
       f"- E76 verdict: **{'CONFIRMED' if a_ok and b_ok and c_ok else 'REFUTED'}**", "",
       "## Training (J)", "", "| Seed | W | steps | final predictive loss | smallest eigenvalue of Cov(h), J / U | directions used, J / U | seconds |", "|---|---|---|---|---|---|---|"]
for s in S:
    t = T(s); md.append(f"| {s} | {t['W']:g} | {t['steps']} | {fmt(t['final_pred'], 3)} | {fmt(t['health_J'], 3)} / {fmt(t['health_U'], 3)} | {t['rank_J']} / {t['rank_U']} | {t['seconds']} |")
open(f"{root}/REPORT_E76.md", "w").write("\n".join(md) + "\n"); print("\n".join(md))
